/* Проявление картинки шторкой clip-path.
   Шторка и встречное уменьшение висят на самой картинке, рамка только держит скругление
   и обрезает увеличенный край. Скрытое состояние ставит только JS и только картинкам
   ниже первого экрана, поэтому без JS, в печати и у поисковых роботов всё видно сразу. */
.irc {
  --irc-dur: 800ms;                          /* «драматичное появление» 600–1200ms; строгий стиль 640ms */
  --irc-ease: cubic-bezier(.05, .7, .1, 1);  /* вход с торможением (MD3 emphasized decelerate) */
  --irc-zoom: 1.12;                          /* встречное уменьшение: картинку «открывают», а не двигают */
  --irc-from: inset(100% 0 0 0);             /* по умолчанию: открывается снизу вверх */
  margin: 0;
}
.irc[data-irc="down"]   { --irc-from: inset(0 0 100% 0); }    /* сверху вниз */
.irc[data-irc="right"]  { --irc-from: inset(0 100% 0 0); }    /* слева направо, по ходу чтения */
.irc[data-irc="center"] { --irc-from: inset(50% 50% 50% 50%); } /* из центра к краям */

.irc__frame {
  overflow: hidden;
  overflow: clip;                              /* держит увеличенную картинку в рамке */
  border-radius: var(--irc-radius, 16px);
  background: var(--irc-bg, transparent);      /* можно подложить цвет поверхности как заглушку */
}
.irc__img { display: block; width: 100%; height: auto; }
.irc__cap { margin-top: 12px; font-size: 15px; line-height: 1.5; color: var(--text-muted, currentColor); }

@media (max-width: 640px) {                    /* телефон: короче и спокойнее */
  .irc { --irc-dur: 640ms; --irc-zoom: 1.06; }
}

/* подпись проявляется после картинки и заканчивает раньше неё */
.irc[data-irc-state="wait"] .irc__cap { opacity: 0; }
.irc[data-irc-state="in"] .irc__cap {
  transition: opacity calc(var(--irc-dur) * .5) cubic-bezier(.2, 0, 0, 1) calc(var(--irc-delay, 0ms) + var(--irc-dur) * .25);
}

/* Полное движение: шторка + встречное уменьшение, одна длительность и одна кривая */
@media (prefers-reduced-motion: no-preference) {
  .irc[data-irc-state="wait"] .irc__img {
    clip-path: var(--irc-from);
    transform: scale(var(--irc-zoom));
  }
  .irc[data-irc-state="in"] .irc__img {
    clip-path: inset(0 0 0 0);
    transition: clip-path var(--irc-dur) var(--irc-ease) var(--irc-delay, 0ms), transform var(--irc-dur) var(--irc-ease) var(--irc-delay, 0ms);
  }
}

/* Уменьшение движения (уровень «смягчить»): без шторки и без масштаба,
   картинка и подпись вместе проявляются за 200ms */
@media (prefers-reduced-motion: reduce) {
  .irc[data-irc-state="wait"] .irc__img { opacity: 0; }
  .irc[data-irc-state="in"] .irc__img,
  .irc[data-irc-state="in"] .irc__cap { transition: opacity 200ms linear; }
}

/* клавиатура: ссылка внутри картинки получила фокус — показываем сразу */
.irc[data-irc-state="wait"]:focus-within .irc__img { clip-path: none; transform: none; opacity: 1; }
.irc[data-irc-state="wait"]:focus-within .irc__cap { opacity: 1; }

@media print {
  .irc .irc__img, .irc .irc__cap { clip-path: none !important; transform: none !important; opacity: 1 !important; }
}

