(() => { // Проявление картинки шторкой, без зависимостей. Прячет только картинки НИЖЕ первого экрана.
  const items = document.querySelectorAll('[data-irc]'), d = document;
  if (!items.length || !('IntersectionObserver' in window)) return; // без IO всё просто видно
  let left = 0; // сколько картинок ещё закрыто; на нуле наблюдатели и слушатели снимаются
  const stop = () => { io.disconnect(); near.disconnect(); d.removeEventListener('transitionend', onEnd); d.removeEventListener('focusin', onFocus); };
  const done = (el) => { if (!el.hasAttribute('data-irc-state')) return; // уже открыта (второй вызов из страховки)
    el.removeAttribute('data-irc-state'); el.style.removeProperty('--irc-delay'); if (--left === 0) stop(); }; // картинке возвращаются свои hover
  const onEnd = (e) => { const el = e.target.closest && e.target.closest('[data-irc-state="in"]'); // шторка кончилась
    if (el && e.target.classList.contains('irc__img') && /^(clip-path|opacity)$/.test(e.propertyName)) done(el); };
  const onFocus = (e) => { const el = e.target.closest && e.target.closest('[data-irc-state="wait"]'); // Tab внутри закрытой картинки:
    if (el) { io.unobserve(el); done(el); } }; // открыть сразу и насовсем, иначе с уходом фокуса она закроется снова
  d.addEventListener('transitionend', onEnd); d.addEventListener('focusin', onFocus);
  // Закрытую шторкой картинку браузер считает невидимой и лениво НЕ грузит — грузим сами, за экран до появления
  const near = new IntersectionObserver((es) => es.forEach((e) => {
    const img = e.isIntersecting && e.target.querySelector('img');
    if (img) { near.unobserve(e.target); img.loading = 'eager'; }
  }), { rootMargin: '100% 0px 100% 0px' });
  const ready = (img) => new Promise((ok) => { // шторка стартует, когда картинка загружена и раскодирована
    if (!img) return ok();
    img.loading = 'eager'; setTimeout(ok, 2500); // прыжок по якорю мимо «ближнего» наблюдателя; сеть зависла — дольше 2,5 с не ждём
    const go = () => (img.decode ? img.decode() : Promise.resolve()).catch(() => {}).then(ok);
    if (img.complete) return img.naturalWidth ? go() : ok(); // битая картинка: сразу показать alt
    img.addEventListener('load', go, { once: true }); img.addEventListener('error', ok, { once: true });
  });
  const row = (r) => Math.round(r.top / 16); // картинки одного ряда — одна строка очереди
  const io = new IntersectionObserver((es) => es.filter((e) => e.isIntersecting)
    .sort((a, b) => (row(a.boundingClientRect) - row(b.boundingClientRect)) || (a.boundingClientRect.left - b.boundingClientRect.left))
    .forEach((e, i) => {
      io.unobserve(e.target); // один раз, без повтора при прокрутке назад
      ready(e.target.querySelector('img')).then(() => {
        if (e.target.getAttribute('data-irc-state') !== 'wait') return; // пока грузилась, её уже открыл фокус
        e.target.style.setProperty('--irc-delay', Math.min(i * 90, 270) + 'ms'); // очередь 90ms, потолок 270ms
        e.target.setAttribute('data-irc-state', 'in'); setTimeout(() => done(e.target), 3000); // страховка без transitionend
      });
    }), { rootMargin: '0px 0px -20% 0px' }); // верх дошёл до 80 % экрана; НЕ threshold: длинный скриншот не наберёт 20 % видимости
  items.forEach((el) => { const r = el.getBoundingClientRect(); // видна при загрузке (первый экран, LCP) — не прячем
    if (r.bottom > 0 && r.top < innerHeight) return;
    el.setAttribute('data-irc-state', 'wait'); left++; near.observe(el); io.observe(el); });
  if (!left) stop(); // всё на первом экране — следить не за чем
})();

