// npm i gsap — ScrollTrigger входит в пакет (лицензия GSAP Standard: бесплатно, но не MIT). Без CDN.
// С GSAP поле js не нужно. CSS оставьте (рамка, подпись, печать): data-irc-state GSAP не ставит,
// поэтому правила состояний просто не сработают.
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);

const FROM = { up: 'inset(100% 0% 0% 0%)', down: 'inset(0% 0% 100% 0%)', right: 'inset(0% 100% 0% 0%)', center: 'inset(50% 50% 50% 50%)' };
gsap.matchMedia().add({ full: '(prefers-reduced-motion: no-preference)', reduce: '(prefers-reduced-motion: reduce)' }, ({ conditions }) => {
  gsap.utils.toArray('[data-irc]').forEach((fig) => {
    const r = fig.getBoundingClientRect();
    if (r.bottom > 0 && r.top < innerHeight) return; // первый экран не трогаем (LCP)
    const img = fig.querySelector('.irc__img'), cap = fig.querySelector('.irc__cap');
    // закрытую шторкой картинку браузер лениво не грузит: грузим сами за экран до появления
    ScrollTrigger.create({ trigger: fig, start: 'top bottom+=100%', once: true, onEnter: () => { img.loading = 'eager'; } });
    const tl = gsap.timeline({ scrollTrigger: { trigger: fig, start: 'top 80%', once: true } });
    if (conditions.reduce) { // уровень «смягчить»: только проявление 200ms, без шторки и масштаба
      tl.from([img, cap].filter(Boolean), { opacity: 0, duration: 0.2, ease: 'none', clearProps: 'opacity' });
    } else {
      tl.fromTo(img, { clipPath: FROM[fig.dataset.irc] || FROM.up, scale: 1.12 },
        { clipPath: 'inset(0% 0% 0% 0%)', scale: 1, duration: 0.8, ease: 'expo.out', clearProps: 'clipPath,transform' });
      if (cap) tl.from(cap, { opacity: 0, duration: 0.4, ease: 'power2.out', clearProps: 'opacity' }, 0.2);
    }
  });
}); // при смене настройки matchMedia сам откатывает созданное и собирает заново
